@named
 qif = QIFNeuron(; I_in=
4
)

# We can pass additional events to be included in the final system.

sys = system(qif; discrete_events = [
60
] => [qif.I_in ~ 
10
])
tspan = (
0
, 
100
) 
# ms

prob = ODEProblem(sys, [], tspan)
sol = solve(prob, Tsit5());

fig = rasterplot(qif, sol; threshold=-
40
);
fig

fig = frplot(qif, sol; threshold=-
40
, win_size=
20
);
fig

@named
 inp = ConstantInput(; I=
3
)

connection_rule(inp, nm, weight=
1
)

@named
 nn = HHNeuronExciBlox(I_bg=
0.4
)

g = MetaDiGraph()
add_edge!(g, dbs => nn, weight = 
10.0
)


@named
 sys = system_from_graph(g)
prob = ODEProblem(sys, [], tspan)

transitions_inds = detect_transitions(time, stimulus; atol=
0.001
)
transition_times = time[transitions_inds]
transition_values = stimulus[transitions_inds]
sol = solve(prob, Vern7(), saveat=dt, tstops = transition_times);
